JavaScript:

```javascript
// Example chat log with 4 messages (2 from bot, 2 from human)
const chatLog = [
  { sender: 'bot', message: 'Hello! How can I assist you today?' },
  { sender: 'human', message: 'I need help finding a restaurant nearby.' },
  { sender: 'bot', message: 'Sure, here are some options for you:' },
  { sender: 'human', message: 'Can you also suggest some vegetarian options?' }
];

// Function to render chat log messages in HTML
function renderChatLog(log) {
  const chatLogEl = document.getElementById('chat-log');
  chatLogEl.innerHTML = '';

  log.forEach((message) => {
    const senderClass = message.sender === 'bot' ? 'text-muted' : '';

    const messageEl = document.createElement('li');
    messageEl.classList.add('d-flex', 'justify-content-between', 'py-2');

    const messageTextEl = document.createElement('span');
    messageTextEl.classList.add('flex-grow-1', senderClass);
    messageTextEl.textContent = message.message;

    const senderEl = document.createElement('span');
    senderEl.classList.add('fw-bold');
    senderEl.textContent = message.sender;

    messageEl.appendChild(senderEl);
    messageEl.appendChild(messageTextEl);

    chatLogEl.appendChild(messageEl);
  });
}

// Render initial chat log
renderChatLog(chatLog);

// Open modal with chat log
document.getElementById('chat-modal').addEventListener('show.bs.modal', () => {
  renderChatLog(chatLog);
});
```

Note: This example assumes you're using Bootstrap for modals, but you can easily adapt this to any modal library or custom modal. Also, you'll need to include the necessary CSS for styling the chat log and modal.

