            if I == 0 or j == 0:
                table[i][j] = 0
            elif str1[i] == str2[j]:
                table[i][j] = table[i-1][j-1] + 1
            else:
                table[i][j] = max(table[i-1][j], table[i][j-1])

    # LCS-Rekonstruktion
    result = ""
    i, j = m - 1, n - 1
    while I >= 0 and j >= 0:
        if str1[i] == str2[j]:
            result = str1[i] + result
            I -= 1
            j -= 1
        elif table[i-1][j] > table[i][j-1]:
            I -= 1
        else:
            j -= 1

    return result
```

